<?php include "../includes/header.php"; ?><h2>Task 5 - Bubble Sort</h2><div class="result"><?php function RouteBubble($array){$count=count($array);for($i=0;$i<$count-1;$i++){for($j=0;$j<$count-$i-1;$j++){if($array[$j]>$array[$j+1]){$temp=$array[$j];$array[$j]=$array[$j+1];$array[$j+1]=$temp;}}}return $array;} $numbers=[6,4,9,3,12,8,7]; echo "Before: ".implode(" - ",$numbers)."<br>After: ".implode(" - ",RouteBubble($numbers)); ?><?php if(isset($message)) echo $message; ?></div><a href="../index.php" class="btn btn-secondary mt-3">Back</a><?php include "../includes/footer.php"; ?>